import sys
from functools import lru_cache

def count_numbers_with_power_of_2(n, e):
    power_of_2 = str(2 ** e)
    length = len(power_of_2)

    @lru_cache(None)
    def count_in_range(high):
        if high < int(power_of_2):
            return 0

        high_str = str(high)
        count = 0

        for i in range(len(high_str) - length + 1):
            if high_str[i:i+length] == power_of_2:
                count += 1

        for i in range(len(high_str) - 1):
            prefix = high_str[:i]
            suffix_length = len(high_str) - i - 1
            count += (int(prefix) + 1) * 10 ** suffix_length

        return count

    return count_in_range(n)

